<?php
/** Standalone additive DDL/FK/index tests. This deliberately does not execute the MySQL-only CompanyLeads writer on SQLite. */
require __DIR__.'/issuers_core_support.php';require APPPATH.'services/CompanyLeadMetadataSchema.php';require APPPATH.'services/CompanyLeadsSchema.php';
$f=essentialFixture('1.0.2',1);$db=$f->db;$p=$f->prefix;$driver=$db->driver();
register_shutdown_function(static function()use($db,$p){$db->pdo->exec('DROP TABLE IF EXISTS `'.$p.'company_lead_metadata`');$db->pdo->exec('DROP TABLE IF EXISTS `'.$p.'company_leads`');essentialCleanup();});
$db->query('CREATE TABLE '.$p.'company_leads(id int unsigned NOT NULL PRIMARY KEY,issuer_id int unsigned NOT NULL,UNIQUE(issuer_id,id))'.($driver==='mysql'?' ENGINE=InnoDB':''));$db->query('INSERT INTO '.$p.'company_leads(id,issuer_id) VALUES(1,41),(2,54)');
essentialCheck(CompanyLeadMetadataSchema::available($db,$p)===false,'Before migration the additive table is absent without fabricated backfill');
CompanyLeadMetadataSchema::ensure($db,$p);CompanyLeadMetadataSchema::ensure($db,$p);essentialCheck(CompanyLeadMetadataSchema::available($db,$p),'Idempotent schema ensure installs the exact additive table');
$insert='INSERT INTO '.$p.'company_lead_metadata(lead_id,issuer_id,title,website,address,city,state,zip,default_language,country,lead_value,currency_json,lastcontact,revision,updated_at) VALUES(?,?,\'\',\'\',\'\',\'\',\'\',\'\',\'\',0,NULL,NULL,NULL,1,\'2026-11-05 12:00:00\')';
$db->query($insert,[1,41]);$before=$db->query('SELECT * FROM '.$p.'company_lead_metadata')->result_array();CompanyLeadMetadataSchema::ensure($db,$p);essentialCheck($db->query('SELECT * FROM '.$p.'company_lead_metadata')->result_array()===$before,'Repeating additive DDL preserves all existing row bytes');
$rejected=false;try{$db->query($insert,[2,41]);}catch(PDOException $error){$rejected=true;}essentialCheck($rejected,'Real composite FK rejects metadata for another owner');
$rejected=false;try{$db->query($insert,[999,41]);}catch(PDOException $error){$rejected=true;}essentialCheck($rejected,'Real composite FK rejects a missing parent');
$db->query($driver==='mysql'?'ALTER TABLE '.$p.'company_lead_metadata DROP INDEX lead_metadata_contact':'DROP INDEX '.$p.'lead_metadata_contact');essentialThrows(fn()=>CompanyLeadMetadataSchema::assertValid($db,$p),'company_lead_metadata_schema_invalid','Missing owner/contact index fails schema validation');
$db->query('CREATE INDEX '.($driver==='mysql'?'lead_metadata_contact':$p.'lead_metadata_contact').' ON '.$p.'company_lead_metadata(issuer_id,lastcontact,lead_id)');CompanyLeadMetadataSchema::assertValid($db,$p);
$db->query('ALTER TABLE '.$p.'company_lead_metadata RENAME COLUMN title TO unrecognized_title');essentialThrows(fn()=>CompanyLeadMetadataSchema::assertValid($db,$p),'company_lead_metadata_schema_invalid','Unexpected column name fails without auto-repair');$db->query('ALTER TABLE '.$p.'company_lead_metadata RENAME COLUMN unrecognized_title TO title');CompanyLeadMetadataSchema::assertValid($db,$p);
$db->pdo->beginTransaction();essentialThrows(fn()=>CompanyLeadMetadataSchema::ensure($db,$p),'issuer_outer_transaction_not_allowed','DDL never joins a caller transaction');essentialCheck($db->pdo->inTransaction(),'Rejected nested DDL leaves caller transaction ownership intact');$db->pdo->rollBack();
$db->query('DROP TABLE '.$p.'company_lead_metadata');unset($db->data_cache['table_names']);$db->query('UPDATE '.$p.'migrations SET version=489');essentialThrows(fn()=>CompanyLeadMetadataSchema::available($db,$p),'company_lead_metadata_schema_missing','Completed migration marker requires the table and fails closed if it is missing');
if($driver==='sqlite')essentialThrows(fn()=>CompanyLeadsSchema::assertValid($db,$p),'issuer_lead_mysql_required','The canonical Lead writer schema remains MySQL-only');
echo 'Lead metadata additive schema: '.$GLOBALS['essentialChecks'].' checks passed ('.$driver.'); standalone DDL only, not canonical Lead writer evidence.'.PHP_EOL;
